function findStrobogrammatic(n) {
  const pairs = [['0', '0'], ['1', '1'], ['6', '9'], ['8', '8'], ['9', '6']];
  const digits = new Array(n);
  const result = [];

  function backtrack(left, right) {
    if (left > right) {
      result.push(digits.join(''));
      return;
    }
    for (const [first, second] of pairs) {
      if (left === right && first !== second) {
        continue;
      }
      if (left === 0 && n > 1 && first === '0') {
        continue;
      }
      digits[left] = first;
      digits[right] = second;
      backtrack(left + 1, right - 1);
    }
  }

  backtrack(0, n - 1);
  return result;
}

