function findStrobogrammatic(n) {
  // Count through every first half over the rotatable digits, mirror it, and keep the strings that survive a rotation check.
  const usable = '01689';
  const turn = new Map([['0', '0'], ['1', '1'], ['6', '9'], ['8', '8'], ['9', '6']]);
  const half = Math.ceil(n / 2);
  const found = [];
  for (let code = 0; code < 5 ** half; code++) {
    let front = '';
    for (let k = 0, c = code; k < half; k++, c = Math.floor(c / 5)) front += usable[c % 5];
    let text = front;
    for (let k = Math.floor(n / 2) - 1; k >= 0; k--) text += turn.get(front[k]);
    if (n > 1 && text[0] === '0') continue;
    const rotated = text.split('').reverse().map(d => turn.get(d)).join('');
    if (rotated === text) found.push(text);
  }
  return found;
}

